"use client";

import { useEffect, useRef, useState } from "react";
import type * as Leaflet from "leaflet";
import "leaflet/dist/leaflet.css";
import { ds } from "@/data/design-tokens";
import { RISK_LABELS, type RiskLevel, type Territory } from "@/data/explore/types";

/**
 * Real map for the first fold: the 18 analysed municipalities (IBGE limits)
 * coloured by risk, over satellite imagery, with the MODIS 2001–2024
 * degradation polygons as an optional layer. Static GeoJSON in /public/geo,
 * generated by the pipeline — nothing is computed in the browser.
 */

const MUNICIPIOS_URL = "/geo/municipios-analisados.geojson";
const DEGRADACAO_URL = "/geo/degradacao-modis.geojson";

const CLASS_COLORS: Record<string, string> = {
  degradado: "#b0301f",
  melhora: "#6f9b6a",
  controle_estavel: "#d9b45a",
};
const CLASS_LABELS: Record<string, string> = {
  degradado: "Degrading",
  melhora: "Improving",
  controle_estavel: "Stable control",
};

function riskColor(risk: RiskLevel | undefined): string {
  if (risk === "critico") return ds.divergent.low;
  if (risk === "alto") return ds.brand.terra;
  if (risk === "moderado") return ds.divergent.lowMid;
  return ds.neutrals.border;
}

type MunProps = { id: string; name: string; uf: string };

export function ExploreMap({
  municipalities,
  selectedId,
  onSelect,
}: {
  municipalities: Territory[];
  selectedId: string | null;
  onSelect: (id: string) => void;
}) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<Leaflet.Map | null>(null);
  const munLayerRef = useRef<Leaflet.GeoJSON | null>(null);
  const degLayerRef = useRef<Leaflet.GeoJSON | null>(null);
  const LRef = useRef<typeof Leaflet | null>(null);
  const onSelectRef = useRef(onSelect);
  const [showDegradation, setShowDegradation] = useState(false);
  const [error, setError] = useState<string | null>(null);

  onSelectRef.current = onSelect;
  const byId = useRef(new Map<string, Territory>());
  byId.current = new Map(municipalities.map((t) => [t.id, t]));

  // Map + municipality layer (once)
  useEffect(() => {
    let cancelled = false;
    (async () => {
      const L = (await import("leaflet")).default;
      if (cancelled || !containerRef.current || mapRef.current) return;
      LRef.current = L;
      const map = L.map(containerRef.current, {
        zoomControl: false,
        scrollWheelZoom: false,
        attributionControl: true,
      }).setView([-8.2, -38.6], 6);
      L.control.zoom({ position: "bottomright" }).addTo(map);
      L.tileLayer(
        "https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}",
        { maxZoom: 18, attribution: "Esri, Maxar · IBGE · MODIS" }
      ).addTo(map);
      mapRef.current = map;

      try {
        const gj = await fetch(MUNICIPIOS_URL).then((r) => {
          if (!r.ok) throw new Error(`${r.status}`);
          return r.json();
        });
        if (cancelled) return;
        const layer = L.geoJSON(gj, {
          onEachFeature: (f, l) => {
            const p = f.properties as MunProps;
            const t = byId.current.get(p.id);
            const risk = t ? RISK_LABELS[t.risk] : "—";
            l.bindTooltip(`${p.name}/${p.uf} · ${risk} risk`, { sticky: true });
            l.on("click", () => onSelectRef.current(p.id));
          },
        }).addTo(map);
        munLayerRef.current = layer;
        map.fitBounds(layer.getBounds(), { padding: [12, 12] });
        restyle();
      } catch (e) {
        setError(`Could not load municipality limits (${(e as Error).message}).`);
      }
    })();
    return () => {
      cancelled = true;
      mapRef.current?.remove();
      mapRef.current = null;
      munLayerRef.current = null;
      degLayerRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  function restyle() {
    const layer = munLayerRef.current;
    if (!layer) return;
    layer.eachLayer((l) => {
      const path = l as Leaflet.Path & { feature?: GeoJSON.Feature };
      const id = (path.feature?.properties as MunProps | undefined)?.id;
      const t = id ? byId.current.get(id) : undefined;
      const active = id === selectedId;
      path.setStyle({
        color: active ? ds.brand.areia : riskColor(t?.risk),
        weight: active ? 3.5 : 2,
        fillColor: riskColor(t?.risk),
        fillOpacity: active ? 0.45 : 0.28,
      });
      if (active) path.bringToFront();
    });
  }

  // Selection / risk changes
  useEffect(() => {
    restyle();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedId, municipalities]);

  // Optional MODIS degradation layer (lazy)
  useEffect(() => {
    const map = mapRef.current;
    const L = LRef.current;
    if (!map || !L) return;
    if (!showDegradation) {
      if (degLayerRef.current) map.removeLayer(degLayerRef.current);
      return;
    }
    let cancelled = false;
    (async () => {
      if (!degLayerRef.current) {
        try {
          const gj = await fetch(DEGRADACAO_URL).then((r) => r.json());
          if (cancelled) return;
          degLayerRef.current = L.geoJSON(gj, {
            interactive: true,
            style: (f) => {
              const c = CLASS_COLORS[f?.properties?.classe] ?? "#999";
              return { color: c, weight: 0.4, fillColor: c, fillOpacity: 0.5 };
            },
            onEachFeature: (f, l) =>
              l.bindTooltip(
                `${CLASS_LABELS[f.properties.classe] ?? f.properties.classe} · ${Number(
                  f.properties.area_ha
                ).toLocaleString("en-US")} ha`
              ),
          });
        } catch {
          setError("Could not load the MODIS degradation layer.");
          return;
        }
      }
      if (cancelled || !degLayerRef.current) return;
      degLayerRef.current.addTo(map);
      munLayerRef.current?.bringToFront();
    })();
    return () => {
      cancelled = true;
    };
  }, [showDegradation]);

  return (
    <div className="flex h-full min-h-0 flex-col rounded-md border border-border bg-card p-3 shadow-sm sm:p-4">
      <div className="mb-2 flex flex-wrap items-start justify-between gap-2">
        <div className="min-w-0">
          <h2 className="font-display text-base text-olive sm:text-lg">
            Desertification susceptibility under climate stress
          </h2>
          <p className="mt-0.5 text-xs text-muted-foreground">
            18 analysed municipalities · click one for its evidence
          </p>
        </div>
        <ul className="flex flex-wrap gap-1.5">
          {(
            [
              ["critico", ds.divergent.low],
              ["alto", ds.brand.terra],
              ["moderado", ds.divergent.lowMid],
            ] as const
          ).map(([k, c]) => (
            <li
              key={k}
              className="flex items-center gap-1 text-[0.6rem] text-muted-foreground"
            >
              <span className="h-2 w-2 rounded-sm" style={{ background: c }} />
              {RISK_LABELS[k]}
            </li>
          ))}
        </ul>
      </div>

      <div className="relative isolate min-h-[300px] flex-1 overflow-hidden rounded-md sm:min-h-[360px] md:min-h-[400px]">
        <div
          ref={containerRef}
          className="absolute inset-0"
          role="region"
          aria-label="Map of the analysed municipalities by risk"
        />
        <button
          type="button"
          onClick={() => setShowDegradation((v) => !v)}
          aria-pressed={showDegradation}
          className={
            "absolute left-2 top-2 z-[500] rounded-md border px-2 py-1 text-[0.7rem] shadow-sm transition-colors " +
            (showDegradation
              ? "border-primary bg-primary text-primary-foreground"
              : "border-white/60 bg-white text-neutral-900 hover:bg-neutral-100")
          }
        >
          MODIS degradation 2001–2024
        </button>
        {showDegradation && (
          <ul className="absolute bottom-2 left-2 z-[500] flex gap-2 rounded-md bg-white px-2 py-1 shadow-sm">
            {Object.entries(CLASS_LABELS).map(([k, label]) => (
              <li key={k} className="flex items-center gap-1 text-[0.6rem] text-neutral-900">
                <span className="h-2 w-2 rounded-sm" style={{ background: CLASS_COLORS[k] }} />
                {label}
              </li>
            ))}
          </ul>
        )}
        {error && (
          <p className="absolute inset-x-2 bottom-2 z-[500] rounded-md bg-white px-2 py-1 text-xs text-neutral-700">
            {error}
          </p>
        )}
      </div>
    </div>
  );
}
